use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_analysis_request_in: Option<Common::AnalysisRequest_Impl>,
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_analysis_request_in(container.api_analysis_request_in);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(analysis_request_in: Option<Common::AnalysisRequest_Impl>)
{
  put_analysis_request_in(analysis_request_in);
}

/// setter for IN EventDataPort
pub fn put_analysis_request_in(value: Option<Common::AnalysisRequest_Impl>)
{
  *extern_api::IN_analysis_request_in.lock().unwrap_or_else(|e| e.into_inner()) = value
}

/// getter for OUT EventDataPort
pub fn get_analysis_request_out() -> Option<Common::AnalysisRequest_Impl>
{
  return extern_api::OUT_analysis_request_out.lock().unwrap_or_else(|e| e.into_inner()).clone()
}
